import{_ as e,H as t,f as d,b as s,j as a,i as c}from"./chunks/framework.DLd0CbzH.js";const n="/app-mockup-ru.webp",m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ОмниКрафт ЕРП","text":"Автоматизация и учет бизнеса и личного капитала","tagline":"Профессиональная система комфортного учета для индивидуальных ремесленников, предпринимателей и микропроизводств. Программа плавно расширяет возможности вместе с вашим ростом.","image":{"src":"/logo.svg","alt":"Логотип ОмниКрафт ЕРП"},"actions":[{"theme":"brand","text":"Скачать для Windows ↓","link":"https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe"},{"theme":"alt","text":"Читать документацию →","link":"/ru/docs/introduction"}]}},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md"}'),l={name:"ru/index.md"};function r(o,i,v,p,h,g){return t(),d("div",null,[...i[0]||(i[0]=[s("div",{id:"notice-banner",class:"notice-banner"},[s("div",{class:"notice-content"},[s("span",{class:"notice-icon"},"⚠️"),s("p",null,[a(" Сайт находится в стадии заполнения, но бета-версия программы уже доступна для скачивания."),s("br"),a(" В ближайшее время мы откроем покупку лицензий и подготовим все юридические документы. ")])]),s("button",{class:"notice-close",onclick:"document.getElementById('notice-banner').style.display='none'"},"×")],-1),c('<div class="custom-section showcase-section" style="padding-bottom:4rem;"><div class="section-container"><div class="showcase-wrapper"><div class="showcase-window"><div class="window-header"><span class="dot red"></span><span class="dot yellow"></span><span class="dot green"></span></div><img src="'+n+'" alt="Интерфейс ОмниКрафт ЕРП" class="ui-screenshot"><div class="window-fade"></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Точность, заложенная в архитектуру</h2><p class="section-subtitle">ОмниКрафт ЕРП исключает человеческий фактор. Математика работает под капотом, позволяя вам сосредоточиться на создании продукта.</p></div><div class="bento-grid"><div class="bento-card"><h3>Умное снабжение (Алгоритм МАК)</h3><p><strong>Механика:</strong> Партионное распределение стоимости логистики и автоматический расчет скользящей средней цены сырья при каждой закупке.<br><br><strong>Результат:</strong> Идеально точная стоимость материалов на складе. Никаких ручных высчитываний пропорций доставки для мелкой фурнитуры.</p></div><div class="bento-card"><h3>Интеллектуальный верстак</h3><p><strong>Механика:</strong> Динамическая очередь заказов с каскадным резервированием ресурсов сверху вниз.<br><br><strong>Результат:</strong> Программа выявляет дефицит материалов до того, как вы начали кроить. Склад надежно защищен от ухода в математический минус.</p></div><div class="bento-card"><h3>Списание по методу ФИФО</h3><p><strong>Механика:</strong> Себестоимость готовой продукции жестко фиксируется в момент её схода с верстака.<br><br><strong>Результат:</strong> Честная картина чистой прибыли. Инфляция и скачки цен на свежее сырье не искажают рентабельность уже произведенных и лежащих на витринских полках партий.</p></div><div class="bento-card"><h3>Автономность и Безопасность</h3><p><strong>Механика:</strong> Локальная архитектура (Локал-Фёрст), журналирование операций (ВАЛ) и автоматическое резервное копирование по схеме ГФС.<br><br><strong>Результат:</strong> Финансовые данные лежат только на вашем ПК. База защищена от сбоев питания, а вы не зависите от облачных подписок и качества интернета.</p></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Единый непрерывный поток</h2><p class="section-subtitle">Одно действие автоматически обновляет всю систему. Никакого двойного ввода данных.</p></div><div class="sleek-pipeline"><div class="sleek-step"><div class="step-badge">01</div><h3>Снабжение</h3><p>Оприходование активов (с авто-расчетом амортизации) и партионная закупка сырья на склад.</p></div><div class="sleek-step"><div class="step-badge">02</div><h3>Калькуляция</h3><p>Создание рецепта изделия с учетом вашей часовой ставки, нормо-часов и накладных расходов.</p></div><div class="sleek-step"><div class="step-badge">03</div><h3>Производство</h3><p>Завершение пошива списывает сырье со склада и зачисляет готовый товар на витрину.</p></div><div class="sleek-step"><div class="step-badge">04</div><h3>Продажа</h3><p>Пробитие чека на кассовом терминале списывает товар и делает двойную запись выручки в журнал ДДС.</p></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Единая математика для любого ремесла</h2><p class="section-subtitle">Принципы себестоимости универсальны. ОмниКрафт ЕРП адаптируется под специфику материалов вашей ниши.</p></div><div class="audience-grid"><div class="audience-card"><h4>Кожевенное дело</h4><p>дм² шкур, метры стропы, фурнитура</p></div><div class="audience-card"><h4>Столярные мастерские</h4><p>м³ древесины, листы, износ станков</p></div><div class="audience-card"><h4>Керамика</h4><p>кг глины, литры глазури, обжиг</p></div><div class="audience-card"><h4>Швейные студии</h4><p>рулоны тканей, нитки, нормо-часы</p></div><div class="audience-card"><h4>Ювелирное дело</h4><p>граммы металлов, штучные камни</p></div><div class="audience-card"><h4>Свечеварение</h4><p>кг воска, аромамасла, фитили</p></div><div class="audience-card"><h4>Косметика и мыло</h4><p>масла, щелочь, мл отдушек</p></div><div class="audience-card"><h4>Создание обуви</h4><p>колодки, подошвы, спец. химия</p></div><div class="audience-card"><h4>Кузнечное дело</h4><p>поковки, рукояти, износ лент</p></div><div class="audience-card"><h4>Художники и декор</h4><p>холсты, краски, эпоксидная смола</p></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="split-layout"><div class="split-left"><h2 class="gradient-text text-left">Приборная панель бизнеса</h2><p>ОмниКрафт ЕРП собирает операционную статистику каждого вашего рабочего пространства (локальная аналитика), позволяя принимать решения на основе твердых цифр.</p><ul style="list-style:none;padding:0;margin-top:2rem;"><li style="margin-bottom:1.5rem;"><strong>⏱️ Рейтинг маржинальности времени (окупаемость времени — РОИ)</strong><br><span style="color:var(--vp-c-text-2);font-size:0.95rem;">Программа показывает чистую прибыль в час для каждого изделия. Вы точно знаете, какая модель приносит 1500 ₽/час, а какая лишь 300 ₽/час, съедая ваше время.</span></li><li style="margin-bottom:1.5rem;"><strong>🎯 Точка безубыточности</strong><br><span style="color:var(--vp-c-text-2);font-size:0.95rem;">Сколько нужно продать в месяц, чтобы просто покрыть аренду, подписки и износ оборудования? Индикатор подскажет минимальный план.</span></li><li><strong>📈 Финансовый пульс</strong><br><span style="color:var(--vp-c-text-2);font-size:0.95rem;">Наглядные графики соотношения выручки, общих расходов и чистой прибыли в динамике полугода.</span></li></ul></div><div class="split-right"></div></div></div></div><div class="custom-section section-dark-2 pro-section"><div class="section-container"><div class="section-header"><h2 class="gradient-text">ПРО: От управления мастерской<br>к управлению капиталом</h2><p class="section-subtitle">Для людей с бизнес-мышлением. Глобальный контур (макроаналитика), объединяющий все ваши проекты и личные активы.</p></div><div class="bento-grid pro-grid"><div class="bento-card span-full"><h3 style="color:var(--vp-c-brand);">Мультипространства и Цели</h3><p>Ведите неограниченное количество независимых бизнесов (например, кожевенная мастерская и продажа выкроек в электронном виде) в изолированных базах данных с разными валютами и наценками. Создавайте пространства для планирования и отслеживания крупных финансовых или жизненных целей.</p></div><div class="bento-card"><h3>Глобальный дашборд «Мой капитал»</h3><p>Система автоматически собирает прибыль всех ваших бизнесов, прибавляет личные счета и выводит единый показатель <strong>Чистые активы (Совокупный капитал)</strong>. Вы видите реальную динамику роста своего богатства.</p></div><div class="bento-card"><h3>Свобода от рутины личных трат</h3><p>Больше не нужно вбивать каждый чек за кофе или продукты. Просто актуализируйте остатки на своих банковских картах в программе. Система вычислит дельту между заработком и текущим остатком, автоматически показав сумму ваших повседневных трат на жизнь.</p></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container" style="text-align:center;max-width:800px;margin:0 auto;"><h2 class="gradient-text">Модульная архитектура (Комбайн Омни)</h2><p style="color:var(--vp-c-text-2);font-size:1.1rem;line-height:1.6;margin-bottom:2rem;"> Программа спроектирована так, чтобы расти вместе с усложнением вашего ремесла. В будущем мы представим систему сквозных подключаемых дополнений (модулей), таких как генератор параметрических выкроек, раскройные карты и интеграции с ЧПУ-оборудованием. </p><div style="background:var(--app-glass-bg);border:1px solid var(--app-glass-border);padding:2rem;border-radius:20px;"><h4 style="margin-top:0;">Уникальное производство? (Для бизнеса)</h4><p style="color:var(--vp-c-text-2);font-size:0.95rem;margin-bottom:0;"> Если логика вашего ремесла требует специфических расчетов (например, сложная конвертация площадей, многоуровневая химическая рецептура или интеграция нестандартного оборудования), вы можете обратиться к нам. Мы спроектируем и внедрим индивидуальный модуль-плагин специально под ваше производство. </p></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Прозрачная модель лицензирования</h2><p class="section-subtitle">Никаких скрытых платежей. Платите только за тот масштаб, который вам нужен.</p></div><div class="sleek-pricing"><div class="pricing-card"><div class="p-header"><h4>Бесплатная (Пробная)</h4><p>Для старта и тестов</p></div><ul class="p-features"><li>Полноценный конвейер учета</li><li>Без таймера времени</li><li class="warning">Лимит: до 20 чеков (продаж)</li><li class="disabled">После лимита — только чтение</li></ul></div><div class="pricing-card standard"><div class="p-header"><h4>Стандартная</h4><p>Основной инструмент мастера</p></div><ul class="p-features"><li class="active"><strong>Безлимитные продажи</strong></li><li>Полноценный конвейер учета</li><li>Безопасность ВАЛ и авто-бэкапы</li><li>Подписка или бессрочная лицензия</li></ul></div><div class="pricing-card pro-card"><div class="pro-glow"></div><div class="pro-badge">ПРО-РЕЖИМ</div><div class="p-header"><h4>ПРО-расширение</h4><p>Экосистема для бизнеса</p></div><ul class="p-features"><li class="active-pro"><strong>Вкладка «Мой Капитал»</strong></li><li class="active-pro"><strong>Мультипространства</strong></li><li>Сжатый резервный архив</li><li>Единоразовый апгрейд (навсегда)</li></ul></div></div><div class="pricing-notice"><strong>Специализированные дополнения (модули):</strong> Нишевые инструменты под конкретные задачи оплачиваются единоразово и отдельно. Вы не переплачиваете за функции, которыми не пользуетесь. </div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Часто задаваемые вопросы</h2></div><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Я веду учет в Экселе. Сложно ли перейти на ОмниКрафт ЕРП?</summary><div class="faq-content"><p>Переход занимает минимум времени. Вам не нужно переносить всю историю старых продаж. Достаточно использовать подход «оценочной точки старта»: внесите текущее оборудование в Мастерскую, забейте фактические остатки материалов на Склад и укажите историческое сальдо в ДДС. Программа подхватит математику и начнет точный учет с этого дня.</p></div></details><details class="faq-item"><summary class="faq-summary">Что будет, если мой компьютер сломается?</summary><div class="faq-content"><p>Программа имеет мощную систему автономных бэкапов. Помимо автоматических теневых копий, вы можете в 1 клик сделать выгрузку всей базы данных в сжатый резервный архив и сохранить его в облаке или на флешке. При покупке нового ПК достаточно установить программу и импортировать этот архив — вся экосистема восстановится за пару секунд.</p></div></details><details class="faq-item"><summary class="faq-summary">Есть ли версия для Mac OS или Linux?</summary><div class="faq-content"><p>В данный момент мы собираем установочный пакет только для Windows. Однако ядро системы абсолютно кроссплатформенное. Разработка и релиз нативных версий для Mac OS и Linux планируются в будущих обновлениях.</p></div></details></div></div></div><div class="custom-cta-block"><h2 class="gradient-text">Спроектировано в мастерской.<br>Написано для ремесленников.</h2><div class="cta-buttons"><a class="vp-button brand" href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe">⬇ Скачать для Windows</a><a class="vp-button alt" href="/ru/docs/introduction">Читать документацию</a></div><div class="footer-links"><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank">Репозиторий проекта</a><a href="/ru/docs/licenses">О лицензиях</a><a href="/ru/docs/about">О разработчике</a></div></div>',10)])])}const b=e(l,[["render",r]]);export{m as __pageData,b as default};
